package com.broandbro.qrapp.partnerreports;

import java.math.BigDecimal;

/**
 * RFC 4180 style CSV builder. Text cells are always quoted and neutralised against spreadsheet formula
 * injection; numbers and dates are written raw because they are generated by the server, never user text.
 */
final class CsvWriter {
    private static final String EOL = "\r\n";
    private final StringBuilder out = new StringBuilder();

    CsvWriter row(Object... cells) {
        for (int i = 0; i < cells.length; i++) {
            if (i > 0) out.append(',');
            out.append(cell(cells[i]));
        }
        out.append(EOL);
        return this;
    }

    CsvWriter blank() {
        out.append(EOL);
        return this;
    }

    byte[] toBytes() {
        return out.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);
    }

    static String cell(Object value) {
        if (value == null) return "";
        if (value instanceof BigDecimal decimal) return decimal.toPlainString();
        if (value instanceof Number || value instanceof Boolean || value instanceof java.time.temporal.TemporalAccessor) {
            return value.toString();
        }
        return quote(neutralise(value.toString()));
    }

    /** Prefixes an apostrophe when a spreadsheet could read the text as a formula. */
    static String neutralise(String text) {
        if (text.isEmpty()) return text;
        char first = text.charAt(0);
        boolean dangerous = first == '=' || first == '+' || first == '-' || first == '@'
                || first == '\t' || first == '\r' || first == '\n';
        return dangerous ? "'" + text : text;
    }

    static String quote(String text) {
        return '"' + text.replace("\"", "\"\"") + '"';
    }
}